type Cabinet={name:string;slug:string;status:string;specialty:string;city:string;address:string;phone:string;logo_url:string|null;primary_color:string;trial_ends_at:string;seo_title:string|null;seo_description:string|null;seo_keywords:string|null;seo_canonical_url:string|null;seo_social_image_url:string|null;seo_indexable:boolean}
type PatientSettings={patient_can_request_appointment:boolean;patient_can_confirm_appointment:boolean;patient_can_cancel_appointment:boolean;patient_can_view_payments:boolean;patient_can_download_documents:boolean;patient_requires_validation:boolean;patient_cin_required:boolean;patient_cin_document_required:boolean}
type FeePrices={prices:Record<string,number>;tax_rates:Record<string,number>}
type PaymentSettings={methods:string[];settlement_types:string[];default_method:string;default_settlement_type:string;default_due_days:number;default_installments:number;grace_days:number}
type ReminderChannels=('WHATSAPP'|'ESPACE_PATIENT')[]
type ReminderSettings={appointments:{enabled:boolean;offset_minutes:number;channels:ReminderChannels};payments:{enabled:boolean;overdue_days:number;repeat_days:number;channels:ReminderChannels};cnss:{enabled:boolean;pending_days:number;repeat_days:number;channels:ReminderChannels};cheques:{enabled:boolean;days_before:number;repeat_days:number}}
type PaymentMethod={id:string;name:string;code:string;main_type:'ESPECE'|'BANQUE';subtype:'CARTE'|'CHEQUE'|'VIREMENT'|null;is_active:boolean}
type BankAccount={id:string;label:string;bank_name:string;account_holder:string;rib:string;iban:string|null;is_default:boolean;is_active:boolean}
type ScheduleDay={weekday:number;is_working:boolean;start_time:string|null;end_time:string|null;break_start_time:string|null;break_end_time:string|null}
type Schedule={days:ScheduleDay[];config:{default_duration_minutes:number;minimum_booking_delay_minutes:number;maximum_appointments_per_day:number|null}}
type TimeOff={id:string;start_date:string;end_date:string;reason:string|null}
type Props={onNavigate:(path:string)=>void}
const defaultPatientSettings:PatientSettings={patient_can_request_appointment:true,patient_can_confirm_appointment:false,patient_can_cancel_appointment:true,patient_can_view_payments:true,patient_can_download_documents:true,patient_requires_validation:true,patient_cin_required:false,patient_cin_document_required:false}
const defaultFeePrices:FeePrices={prices:{CONSULTATION:300,ACTE:0,SOIN:0,TRAITEMENT:0,AUTRE:0},tax_rates:{CONSULTATION:0,ACTE:0,SOIN:0,TRAITEMENT:0,AUTRE:0}}
const defaultPaymentSettings:PaymentSettings={methods:['cash','card','transfer','cheque','other'],settlement_types:['immediate','partial','single_due','installment'],default_method:'cash',default_settlement_type:'immediate',default_due_days:30,default_installments:3,grace_days:0}
const defaultReminderSettings:ReminderSettings={appointments:{enabled:true,offset_minutes:1440,channels:['ESPACE_PATIENT']},payments:{enabled:false,overdue_days:1,repeat_days:7,channels:['ESPACE_PATIENT']},cnss:{enabled:false,pending_days:7,repeat_days:7,channels:['ESPACE_PATIENT']},cheques:{enabled:true,days_before:1,repeat_days:1}}
const paymentMethodNames:Record<string,string>={cash:'Espèces',card:'Carte bancaire',transfer:'Virement bancaire',cheque:'Chèque',other:'Autre'}
const settlementNames:Record<string,string>={immediate:'Paiement immédiat',partial:'Paiement partiel',single_due:'Paiement à échéance',installment:'Plusieurs échéances'}
const feeTypeLabel=(type:string)=>type.toLocaleLowerCase('fr').replace(/_/g,' ').replace(/(^|\s)\p{L}/gu,letter=>letter.toLocaleUpperCase('fr'))
const fieldClass='mt-2 w-full rounded-[8px] border border-atlas-line bg-white px-4 py-3 outline-none focus:border-atlas-teal focus:ring-4 focus:ring-atlas-teal/10 disabled:bg-slate-50'
const specialties=['Médecine générale','Cardiologie','Dermatologie','Pédiatrie','Gynécologie-obstétrique','Ophtalmologie','Oto-rhino-laryngologie (ORL)','Gastro-entérologie','Pneumologie','Neurologie','Psychiatrie','Endocrinologie et diabétologie','Rhumatologie','Néphrologie','Urologie','Chirurgie générale','Chirurgie orthopédique','Médecine interne','Médecine du travail','Médecine physique et réadaptation','Radiologie','Anesthésie-réanimation','Oncologie','Hématologie','Allergologie','Médecine dentaire']

function PaymentMethodToggle({item,readOnly,onToggle}:{item:PaymentMethod;readOnly:boolean;onToggle:()=>void}){const subtypeLabels:Record<string,string>={CARTE:'Carte bancaire',CHEQUE:'Chèque',VIREMENT:'Virement bancaire'};return <button type="button" disabled={readOnly} onClick={onToggle} className="flex w-full items-center justify-between gap-3 rounded-[8px] border border-atlas-line bg-white p-3 text-left disabled:opacity-60"><span><b className="block text-sm">{item.subtype?subtypeLabels[item.subtype]??item.name:item.name}</b>{item.subtype&&<span className="mt-0.5 block text-[10px] font-bold text-slate-400">Sous-type : {item.subtype}</span>}</span><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${item.is_active?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-500'}`}>{item.is_active?'ACTIF':'INACTIF'}</span></button>}
function ReminderChannelChoices({channels,disabled,onToggle}:{channels:ReminderChannels;disabled:boolean;onToggle:(channel:'WHATSAPP'|'ESPACE_PATIENT')=>void}){return <fieldset className="mt-3 sm:mt-0"><legend className="text-sm font-bold">Canaux d’envoi</legend><div className="mt-2 flex flex-wrap gap-2">{([['ESPACE_PATIENT','Espace patient'],['WHATSAPP','WhatsApp']] as const).map(([channel,label])=><label key={channel} className={`flex cursor-pointer items-center gap-2 rounded-[8px] border px-3 py-2 text-xs font-bold ${channels.includes(channel)?'border-atlas-teal bg-white text-atlas-teal':'border-atlas-line bg-slate-50 text-slate-500'}`}><input type="checkbox" disabled={disabled} checked={channels.includes(channel)} onChange={()=>onToggle(channel)} className="accent-atlas-teal"/>{label}</label>)}</div>{channels.includes('WHATSAPP')&&<p className="mt-2 text-[11px] font-semibold text-amber-700">WhatsApp nécessite un modèle approuvé par Meta.</p>}</fieldset>}

type ExpenseSupplier={id:string;name:string;supplier_type:string;tax_id?:string|null;phone?:string|null;email?:string|null};
type SupplierProduct={id:string;supplier_id:string;name:string;category:string;unit:string;default_unit_price_ht:number;tax_rate:number};
function SupplierCatalogSettings({readOnly}:{readOnly:boolean}){
  const session=getSession();const[suppliers,setSuppliers]=useState<ExpenseSupplier[]>([]);const[products,setProducts]=useState<SupplierProduct[]>([]);const[selectedId,setSelectedId]=useState("");
  const[supplierForm,setSupplierForm]=useState({name:"",supplier_type:"Fournitures médicales",tax_id:"",phone:"",email:""});
  const[productForm,setProductForm]=useState({name:"",category:"Fournitures médicales",unit:"unité",default_unit_price_ht:"",tax_rate:"20"});
  const[message,setMessage]=useState("");
  useEffect(()=>{if(!session?.accessToken)return;apiList<ExpenseSupplier>('/expense-suppliers',session.accessToken).then(rows=>{setSuppliers(rows);setSelectedId(current=>current||rows[0]?.id||"")}).catch(error=>setMessage(error instanceof Error?error.message:"Chargement impossible."))},[session?.accessToken]);
  useEffect(()=>{if(!session?.accessToken||!selectedId){setProducts([]);return}apiList<SupplierProduct>(`/supplier-products?supplier_id=${selectedId}`,session.accessToken).then(setProducts).catch(error=>setMessage(error instanceof Error?error.message:"Chargement des produits impossible."))},[session?.accessToken,selectedId]);
  async function addSupplier(){if(!session?.accessToken||readOnly||!supplierForm.name.trim())return;try{const saved=await apiCreate<ExpenseSupplier>('/expense-suppliers',session.accessToken,{...supplierForm,name:supplierForm.name.trim(),tax_id:supplierForm.tax_id.trim()||null,phone:supplierForm.phone.trim()||null,email:supplierForm.email.trim()||null,address:null,is_active:true});setSuppliers(current=>[...current,saved].sort((a,b)=>a.name.localeCompare(b.name)));setSelectedId(saved.id);setSupplierForm({...supplierForm,name:"",tax_id:"",phone:"",email:""});setMessage("Fournisseur ajouté avec succès.")}catch(error){setMessage(error instanceof Error?error.message:"Création impossible.")}}
  async function addProduct(){if(!session?.accessToken||readOnly||!selectedId||!productForm.name.trim()||productForm.default_unit_price_ht==="")return;try{const saved=await apiCreate<SupplierProduct>('/supplier-products',session.accessToken,{...productForm,supplier_id:selectedId,name:productForm.name.trim(),default_unit_price_ht:Number(productForm.default_unit_price_ht),tax_rate:Number(productForm.tax_rate),is_active:true});setProducts(current=>[...current,saved].sort((a,b)=>a.name.localeCompare(b.name)));setProductForm({...productForm,name:"",default_unit_price_ht:""});setMessage("Produit ajouté au catalogue.")}catch(error){setMessage(error instanceof Error?error.message:"Création du produit impossible.")}}
  return <section id="fournisseurs-produits" className="scroll-mt-24 rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><Building2 size={21}/></span><div><h2 className="font-display text-xl font-bold">Fournisseurs et produits</h2><p className="text-xs text-slate-500">Catalogue commun utilisé dans Finance → Dépenses.</p></div></div>
    {message&&<p className="mt-4 rounded-[8px] bg-atlas-mist p-3 text-sm font-semibold text-atlas-petrol">{message}</p>}
    <div className="mt-5 grid gap-6 xl:grid-cols-2"><div className="rounded-[10px] border border-atlas-line p-4"><h3 className="font-bold">Ajouter un fournisseur</h3><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="text-sm font-bold">Nom du fournisseur *<input disabled={readOnly} value={supplierForm.name} onChange={e=>setSupplierForm({...supplierForm,name:e.target.value})} placeholder="Ex. Médical Distribution" className={fieldClass}/></label><label className="text-sm font-bold">Type de fourniture *<input disabled={readOnly} value={supplierForm.supplier_type} onChange={e=>setSupplierForm({...supplierForm,supplier_type:e.target.value})} placeholder="Ex. Consommables médicaux" className={fieldClass}/></label><label className="text-sm font-bold">ICE / Identifiant fiscal<input disabled={readOnly} value={supplierForm.tax_id} onChange={e=>setSupplierForm({...supplierForm,tax_id:e.target.value})} className={fieldClass}/></label><label className="text-sm font-bold">Téléphone<input disabled={readOnly} value={supplierForm.phone} onChange={e=>setSupplierForm({...supplierForm,phone:e.target.value})} className={fieldClass}/></label><label className="text-sm font-bold sm:col-span-2">E-mail<input disabled={readOnly} type="email" value={supplierForm.email} onChange={e=>setSupplierForm({...supplierForm,email:e.target.value})} className={fieldClass}/></label></div><button type="button" disabled={readOnly||!supplierForm.name.trim()} onClick={()=>void addSupplier()} className="mt-4 inline-flex items-center gap-2 rounded-[8px] bg-atlas-teal px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40"><Plus size={16}/>Ajouter le fournisseur</button></div>
      <div className="rounded-[10px] border border-atlas-line p-4"><h3 className="font-bold">Catalogue du fournisseur</h3><label className="mt-3 block text-sm font-bold">Fournisseur à gérer<select value={selectedId} onChange={e=>setSelectedId(e.target.value)} className={fieldClass}><option value="">Choisir</option>{suppliers.map(item=><option key={item.id} value={item.id}>{item.name} · {item.supplier_type}</option>)}</select></label>{selectedId&&<><div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-sm font-bold">Produit / fourniture *<input disabled={readOnly} value={productForm.name} onChange={e=>setProductForm({...productForm,name:e.target.value})} placeholder="Ex. Gants nitrile" className={fieldClass}/></label><label className="text-sm font-bold">Catégorie *<input disabled={readOnly} value={productForm.category} onChange={e=>setProductForm({...productForm,category:e.target.value})} className={fieldClass}/></label><label className="text-sm font-bold">Unité *<input disabled={readOnly} value={productForm.unit} onChange={e=>setProductForm({...productForm,unit:e.target.value})} placeholder="boîte, unité, litre…" className={fieldClass}/></label><label className="text-sm font-bold">Prix unitaire HT (MAD) *<input disabled={readOnly} type="number" min="0" step="0.01" value={productForm.default_unit_price_ht} onChange={e=>setProductForm({...productForm,default_unit_price_ht:e.target.value})} className={fieldClass}/></label><label className="text-sm font-bold">TVA (%) *<input disabled={readOnly} type="number" min="0" max="100" step="0.01" value={productForm.tax_rate} onChange={e=>setProductForm({...productForm,tax_rate:e.target.value})} className={fieldClass}/></label></div><button type="button" disabled={readOnly||!productForm.name.trim()||productForm.default_unit_price_ht===""} onClick={()=>void addProduct()} className="mt-4 inline-flex items-center gap-2 rounded-[8px] bg-atlas-petrol px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40"><Plus size={16}/>Ajouter au catalogue</button></>}</div></div>
    <div className="mt-6 overflow-hidden rounded-[10px] border border-atlas-line"><div className="bg-slate-50 px-4 py-3"><h3 className="font-bold">Produits configurés</h3></div>{products.length?<div className="divide-y divide-atlas-line">{products.map(item=><article key={item.id} className="grid gap-2 p-4 text-sm sm:grid-cols-[1fr_1fr_auto_auto]"><b>{item.name}</b><span className="text-slate-500">{item.category} · {item.unit}</span><span className="font-bold">{Number(item.default_unit_price_ht).toFixed(2)} MAD HT</span><span className="font-bold text-atlas-teal">TVA {Number(item.tax_rate)}%</span></article>)}</div>:<p className="p-6 text-center text-sm text-slate-400">Aucun produit configuré pour ce fournisseur.</p>}</div>
  </section>
}

function SeoSettings({cabinet,readOnly,onChange}:{cabinet:Cabinet;readOnly:boolean;onChange:(changes:Partial<Cabinet>)=>void}){
  const generatedTitle=`${cabinet.name} · ${cabinet.specialty} à ${cabinet.city}`
  const generatedDescription=`Prenez rendez-vous avec ${cabinet.name}, cabinet de ${cabinet.specialty} à ${cabinet.city}.`
  const publicUrl=`${window.location.origin}/cabinet/${encodeURIComponent(cabinet.slug)}`
  const title=cabinet.seo_title||generatedTitle
  const description=cabinet.seo_description||generatedDescription
  return <section id="referencement-seo" className="rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6">
    <div className="flex flex-wrap items-start justify-between gap-4"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><Globe2 size={21}/></span><div><h2 className="font-display text-xl font-bold">Référencement SEO</h2><p className="text-xs text-slate-500">Contrôlez l’affichage du cabinet dans Google et lors du partage du lien.</p></div></div><a href={publicUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-[8px] border border-atlas-line px-4 py-2.5 text-sm font-bold text-atlas-teal hover:border-atlas-teal"><ExternalLink size={16}/>Voir la page publique</a></div>
    <div className="mt-5 grid gap-4 md:grid-cols-2">
      <label className="text-sm font-bold md:col-span-2">Titre SEO <span className="float-end text-xs font-semibold text-slate-400">{(cabinet.seo_title??'').length}/70</span><input disabled={readOnly} maxLength={70} value={cabinet.seo_title??''} onChange={event=>onChange({seo_title:event.target.value||null})} placeholder={generatedTitle} className={fieldClass}/><span className="mt-1.5 block text-xs font-normal text-slate-500">Laissez vide pour utiliser automatiquement le nom, la spécialité et la ville.</span></label>
      <label className="text-sm font-bold md:col-span-2">Méta-description <span className="float-end text-xs font-semibold text-slate-400">{(cabinet.seo_description??'').length}/320</span><textarea disabled={readOnly} maxLength={320} rows={3} value={cabinet.seo_description??''} onChange={event=>onChange({seo_description:event.target.value||null})} placeholder={generatedDescription} className={fieldClass}/></label>
      <label className="text-sm font-bold md:col-span-2">Mots-clés<input disabled={readOnly} maxLength={500} value={cabinet.seo_keywords??''} onChange={event=>onChange({seo_keywords:event.target.value||null})} placeholder={`${cabinet.specialty}, médecin, ${cabinet.city}, rendez-vous médical`} className={fieldClass}/><span className="mt-1.5 block text-xs font-normal text-slate-500">Séparez les expressions par des virgules.</span></label>
      <label className="text-sm font-bold">URL canonique<input disabled={readOnly} type="url" maxLength={500} value={cabinet.seo_canonical_url??''} onChange={event=>onChange({seo_canonical_url:event.target.value||null})} placeholder={publicUrl} className={fieldClass}/></label>
      <label className="text-sm font-bold">Image de partage<input disabled={readOnly} type="url" maxLength={500} value={cabinet.seo_social_image_url??''} onChange={event=>onChange({seo_social_image_url:event.target.value||null})} placeholder="https://exemple.ma/image-cabinet.jpg" className={fieldClass}/></label>
    </div>
    <label className="mt-4 flex items-start justify-between gap-4 rounded-[10px] border border-atlas-line bg-slate-50 p-4"><span><b className="block text-sm">Autoriser l’indexation</b><span className="mt-1 block text-xs leading-5 text-slate-500">Permettre aux moteurs de recherche d’afficher cette page publique.</span></span><input type="checkbox" disabled={readOnly} checked={cabinet.seo_indexable!==false} onChange={event=>onChange({seo_indexable:event.target.checked})} className="mt-1 h-5 w-5 shrink-0 accent-atlas-teal"/></label>
    <div className="mt-5 rounded-[10px] border border-slate-200 bg-white p-4 shadow-sm"><p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Aperçu du résultat Google</p><p className="mt-3 truncate text-xs text-emerald-700">{cabinet.seo_canonical_url||publicUrl}</p><h3 className="mt-1 text-xl font-medium text-blue-700">{title}</h3><p className="mt-1 max-w-3xl text-sm leading-5 text-slate-600">{description}</p></div>
  </section>
}

export function CabinetPage({onNavigate}:Props){
  const session=getSession();const [cabinet,setCabinet]=useState<Cabinet|null>(null);const [patientSettings,setPatientSettings]=useState<PatientSettings>(defaultPatientSettings);const[feePrices,setFeePrices]=useState<FeePrices>(defaultFeePrices);const[paymentSettings,setPaymentSettings]=useState<PaymentSettings>(defaultPaymentSettings);const[reminderSettings,setReminderSettings]=useState<ReminderSettings>(defaultReminderSettings)
  const[paymentMethods,setPaymentMethods]=useState<PaymentMethod[]>([])
  const[bankAccounts,setBankAccounts]=useState<BankAccount[]>([]);const[showBankAccount,setShowBankAccount]=useState(false);const[editingBankAccountId,setEditingBankAccountId]=useState<string|null>(null);const[bankAccountForm,setBankAccountForm]=useState({label:'',bank_name:'',account_holder:'',rib:'',iban:'',is_default:false,is_active:true})
  const[schedule,setSchedule]=useState<Schedule|null>(null);const[timeOffs,setTimeOffs]=useState<TimeOff[]>([]);const[showLeave,setShowLeave]=useState(false);const[leave,setLeave]=useState({start_date:'',end_date:'',reason:''})
  const [logoFile,setLogoFile]=useState<File|null>(null);const [logoPreview,setLogoPreview]=useState('');const [uploadingLogo,setUploadingLogo]=useState(false);const [logoError,setLogoError]=useState('');const [loading,setLoading]=useState(true);const [saving,setSaving]=useState(false);const [copied,setCopied]=useState(false);const [message,setMessage]=useState('');const [newFeeType,setNewFeeType]=useState('');const [newFeePrice,setNewFeePrice]=useState('');const[newFeeTaxRate,setNewFeeTaxRate]=useState('0')
  const readOnly=session?.tenantStatus==='expired'||session?.tenantStatus==='suspended'
  useEffect(()=>{
    if(!session?.accessToken)return
    let active=true
    const token=session.accessToken
    const issues:string[]=[]
    const safe=async<T,>(label:string,promise:Promise<T>,fallback:T):Promise<T>=>{
      try{return await promise}catch(error){issues.push(`${label} : ${error instanceof Error?error.message:'indisponible'}`);return fallback}
    }
    setLoading(true)
    Promise.all([
      safe<Cabinet|null>('Informations du cabinet',apiGet<Cabinet>('/doctor/cabinet',token),null),
      safe('Options de l’espace patient',apiGet<PatientSettings>('/doctor/patient-settings',token),defaultPatientSettings),
      safe('Tarifs',apiGet<FeePrices>('/doctor/fee-settings',token),defaultFeePrices),
      safe('Configuration des paiements',apiGet<PaymentSettings>('/doctor/payment-settings',token),defaultPaymentSettings),
      safe('Relances automatiques',apiGet<ReminderSettings>('/doctor/reminder-settings',token),defaultReminderSettings),
      safe<Schedule|null>('Horaires',apiGet<Schedule>('/doctor/schedule',token),null),
      safe('Absences',apiList<TimeOff>('/doctor/time-offs',token),[]),
      safe('Modes de règlement',apiList<PaymentMethod>('/payment-methods',token),[]),
      safe('Comptes bancaires',apiList<BankAccount>('/bank-accounts',token),[])
    ]).then(([loadedCabinet,settings,prices,paymentConfig,loadedReminders,loadedSchedule,loadedTimeOffs,loadedPaymentMethods,loadedBankAccounts])=>{
      if(!active)return
      setCabinet(loadedCabinet);setPatientSettings(settings);setFeePrices(prices);setPaymentSettings(paymentConfig);setReminderSettings(loadedReminders);setSchedule(loadedSchedule);setTimeOffs(loadedTimeOffs);setPaymentMethods(loadedPaymentMethods);setBankAccounts(loadedBankAccounts)
      setMessage(issues.length?`Certaines sections n’ont pas pu être chargées : ${issues.join(' · ')}`:'')
    }).finally(()=>{if(active)setLoading(false)})
    return()=>{active=false}
  },[session?.accessToken])
  useEffect(()=>{if(!cabinet?.logo_url||!session?.accessToken||logoFile)return;let objectUrl='';apiPreview('/doctor/cabinet/logo',session.accessToken).then(result=>{objectUrl=result.url;setLogoPreview(result.url)}).catch(()=>undefined);return()=>{if(objectUrl)URL.revokeObjectURL(objectUrl)}},[cabinet?.logo_url,logoFile,session?.accessToken])
  useEffect(()=>{if(!loading&&['#tarifs-honoraires','#configuration-paiements'].includes(window.location.hash))window.setTimeout(()=>document.getElementById(window.location.hash.slice(1))?.scrollIntoView({behavior:'smooth',block:'start'}),50)},[loading])
  function set(key:keyof Cabinet,value:string){setCabinet(current=>current?{...current,[key]:value}:current);if(key==='primary_color')applyCabinetTheme(value)}
  async function chooseLogo(file:File|null){if(!file||!session?.accessToken||readOnly)return;setLogoFile(file);setLogoPreview(URL.createObjectURL(file));setUploadingLogo(true);setLogoError('');setMessage('Enregistrement du logo…');try{const updated=await apiUpload<Cabinet>('/doctor/cabinet/logo',session.accessToken,{file});setCabinet(current=>current?{...current,logo_url:updated.logo_url}:updated);setLogoFile(null);setMessage('Logo enregistré avec succès. Il sera utilisé sur les nouveaux documents PDF.')}catch(error){const detail=error instanceof Error?error.message:'Enregistrement du logo impossible.';setLogoFile(null);setLogoError(detail);setMessage(detail)}finally{setUploadingLogo(false)}}
  async function copyCode(){if(!cabinet)return;await navigator.clipboard.writeText(cabinet.slug);setCopied(true);window.setTimeout(()=>setCopied(false),1800)}
  function addFeeType(){const key=newFeeType.trim().toLocaleUpperCase('fr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]+/g,'_').replace(/^_+|_+$/g,'');if(!key){setMessage('Saisissez un nom de type valide.');return}if(feePrices.prices[key]!==undefined){setMessage('Ce type d’honoraire existe déjà.');return}setFeePrices({prices:{...feePrices.prices,[key]:Number(newFeePrice)||0},tax_rates:{...feePrices.tax_rates,[key]:Number(newFeeTaxRate)||0}});setNewFeeType('');setNewFeePrice('');setNewFeeTaxRate('0');setMessage('')}
  function removeFeeType(type:string){if(Object.keys(feePrices.prices).length<=1){setMessage('Conservez au moins un type d’honoraire.');return}setFeePrices({prices:Object.fromEntries(Object.entries(feePrices.prices).filter(([key])=>key!==type)),tax_rates:Object.fromEntries(Object.entries(feePrices.tax_rates).filter(([key])=>key!==type))})}
  async function save(event:FormEvent){event.preventDefault();if(!cabinet||!session?.accessToken||readOnly)return;setSaving(true);setMessage('');try{const updated=await apiUpdate<Cabinet>('/doctor/cabinet',session.accessToken,{name:cabinet.name.trim(),specialty:cabinet.specialty.trim(),phone:cabinet.phone.trim(),city:cabinet.city.trim(),address:cabinet.address.trim(),primary_color:cabinet.primary_color||DEFAULT_COLOR,seo_title:cabinet.seo_title?.trim()||null,seo_description:cabinet.seo_description?.trim()||null,seo_keywords:cabinet.seo_keywords?.trim()||null,seo_canonical_url:cabinet.seo_canonical_url?.trim()||null,seo_social_image_url:cabinet.seo_social_image_url?.trim()||null,seo_indexable:cabinet.seo_indexable!==false});await Promise.all([apiUpdate('/doctor/patient-settings',session.accessToken,patientSettings),apiUpdate('/doctor/fee-settings',session.accessToken,feePrices),apiUpdate('/doctor/payment-settings',session.accessToken,paymentSettings),apiUpdate('/doctor/reminder-settings',session.accessToken,reminderSettings),schedule&&apiUpdate('/doctor/schedule',session.accessToken,schedule)]);setCabinet(updated);applyCabinetTheme(updated.primary_color);setLogoFile(null);setMessage('Configuration enregistrée avec succès.')}catch(error){setMessage(error instanceof Error?error.message:'Enregistrement impossible.')}finally{setSaving(false)}}
  async function addLeave(){if(!session?.accessToken||!leave.start_date||!leave.end_date)return;try{const created=await apiCreate<TimeOff>('/doctor/time-offs',session.accessToken,leave);setTimeOffs([...timeOffs,created]);setLeave({start_date:'',end_date:'',reason:''});setShowLeave(false);setMessage('Absence ajoutée avec succès.')}catch(error){setMessage(error instanceof Error?error.message:'Ajout impossible.')}}
  async function togglePaymentMethod(item:PaymentMethod){if(!session?.accessToken||readOnly)return;try{const updated=await apiUpdate<PaymentMethod>(`/payment-methods/${item.id}`,session.accessToken,{is_active:!item.is_active});setPaymentMethods(current=>current.map(value=>value.id===updated.id?updated:value));setMessage('Mode de règlement mis à jour avec succès.')}catch(error){setMessage(error instanceof Error?error.message:'Modification impossible.')}}
  function openBankAccount(item?:BankAccount){setEditingBankAccountId(item?.id??null);setBankAccountForm(item?{label:item.label,bank_name:item.bank_name,account_holder:item.account_holder,rib:item.rib,iban:item.iban??'',is_default:item.is_default,is_active:item.is_active}:{label:'',bank_name:'',account_holder:cabinet?.name??'',rib:'',iban:'',is_default:bankAccounts.length===0,is_active:true});setShowBankAccount(true)}
  async function saveBankAccount(){if(!session?.accessToken||readOnly)return;try{const payload={...bankAccountForm,label:bankAccountForm.label.trim(),bank_name:bankAccountForm.bank_name.trim(),account_holder:bankAccountForm.account_holder.trim(),rib:bankAccountForm.rib.trim(),iban:bankAccountForm.iban.trim()||null};const saved=editingBankAccountId?await apiUpdate<BankAccount>(`/bank-accounts/${editingBankAccountId}`,session.accessToken,payload):await apiCreate<BankAccount>('/bank-accounts',session.accessToken,payload);setBankAccounts(current=>{const next=editingBankAccountId?current.map(item=>item.id===saved.id?saved:item):[...current,saved];return next.map(item=>saved.is_default&&item.id!==saved.id?{...item,is_default:false}:item).sort((a,b)=>Number(b.is_default)-Number(a.is_default)||a.label.localeCompare(b.label))});setShowBankAccount(false);setEditingBankAccountId(null);setMessage('Compte bancaire enregistré avec succès.')}catch(error){setMessage(error instanceof Error?error.message:'Enregistrement du compte impossible.')}}
  async function updateBankAccount(item:BankAccount,changes:Partial<BankAccount>){if(!session?.accessToken||readOnly)return;try{const updated=await apiUpdate<BankAccount>(`/bank-accounts/${item.id}`,session.accessToken,changes);setBankAccounts(current=>current.map(value=>value.id===updated.id?updated:updated.is_default?{...value,is_default:false}:value).sort((a,b)=>Number(b.is_default)-Number(a.is_default)||a.label.localeCompare(b.label)));setMessage('Compte bancaire mis à jour avec succès.')}catch(error){setMessage(error instanceof Error?error.message:'Modification du compte impossible.')}}
  function toggleReminderChannel(section:keyof ReminderSettings,channel:'WHATSAPP'|'ESPACE_PATIENT'){
    const current=reminderSettings[section];const exists=current.channels.includes(channel)
    if(exists&&current.channels.length===1){setMessage('Conservez au moins un canal pour cette relance.');return}
    setReminderSettings({...reminderSettings,[section]:{...current,channels:exists?current.channels.filter(item=>item!==channel):[...current.channels,channel]}})
  }

  return <MedecinLayout cabinetName={cabinet?.name??'Cabinet'} onNavigate={onNavigate} onLogout={()=>{logout();onNavigate('/login')}}><div className="mx-auto max-w-5xl px-5 py-6 md:px-8">
    <header className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-sm font-bold uppercase tracking-wide text-atlas-teal">Paramètres</p><h1 className="mt-1 font-display text-3xl font-bold">Configuration du cabinet</h1><p className="mt-2 text-sm text-slate-600">Personnalisez vos informations et choisissez ce que vos patients peuvent faire.</p></div>{cabinet&&<InstanceStatusBadge status={cabinet.status}/>}</header>
    <div className="mt-6"><InterfaceLanguageSettings/></div>
    {message&&<p className={`mt-5 rounded-[8px] border px-4 py-3 text-sm font-bold ${message.includes('succès')?'border-emerald-200 bg-emerald-50 text-emerald-700':'border-amber-200 bg-amber-50 text-amber-800'}`}>{message}</p>}
    {loading?<div className="mt-6 rounded-[12px] border border-atlas-line bg-white p-10 text-center text-sm font-semibold text-slate-500">Chargement de la configuration…</div>:cabinet&&<form onSubmit={save} className="mt-6 space-y-6">
      <SeoSettings cabinet={cabinet} readOnly={readOnly} onChange={changes=>setCabinet(current=>current?{...current,...changes}:current)}/>
      <section className="rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><Settings2 size={21}/></span><div><h2 className="font-display text-xl font-bold">Services et assistance</h2><p className="text-xs text-slate-500">Accédez aux fonctions secondaires sans surcharger le menu principal</p></div></div><div className="mt-5 grid gap-3 md:grid-cols-2"><button type="button" onClick={()=>onNavigate('/doctor/reviews')} className="flex items-center gap-4 rounded-[10px] border border-atlas-line p-4 text-left transition hover:border-atlas-teal hover:bg-atlas-mist/30"><span className="grid h-10 w-10 place-items-center rounded-full bg-amber-50 text-amber-600"><Star size={20}/></span><span><b className="block">Avis patients</b><span className="mt-1 block text-xs text-slate-500">Notes, commentaires et statistiques</span></span></button><button type="button" onClick={()=>onNavigate('/doctor/support')} className="flex items-center gap-4 rounded-[10px] border border-atlas-line p-4 text-left transition hover:border-atlas-teal hover:bg-atlas-mist/30"><span className="grid h-10 w-10 place-items-center rounded-full bg-blue-50 text-blue-600"><LifeBuoy size={20}/></span><span><b className="block">Support FADAA</b><span className="mt-1 block text-xs text-slate-500">Contacter et suivre les réponses du Super Admin</span></span></button></div></section>
      <section id="tarifs-honoraires" className="scroll-mt-24 overflow-hidden rounded-[12px] border border-atlas-line bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-atlas-line p-5 md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><BadgeDollarSign size={22}/></span><div><h2 className="font-display text-xl font-bold">Tarifs des honoraires</h2><p className="text-xs text-slate-500">Définissez le prix HT et la TVA appliqués automatiquement</p></div></div><span className="rounded-full bg-atlas-mist px-3 py-1.5 text-xs font-bold text-atlas-teal">{Object.keys(feePrices.prices).length} type(s)</span></div>
        <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th className="px-5 py-3 font-bold">Type d’honoraire</th><th className="px-5 py-3 font-bold">Prix par défaut</th><th className="px-5 py-3 font-bold">TVA</th><th className="px-5 py-3 text-right font-bold">Action</th></tr></thead><tbody className="divide-y divide-atlas-line">{Object.entries(feePrices.prices).map(([type,price])=><tr key={type} className="hover:bg-slate-50/70"><td className="px-5 py-4"><p className="font-bold text-atlas-ink">{feeTypeLabel(type)}</p><p className="mt-0.5 font-mono text-[10px] text-slate-400">{type}</p></td><td className="px-5 py-3"><div className="relative max-w-52"><input aria-label={`Prix ${feeTypeLabel(type)}`} disabled={readOnly} type="number" min="0" step="0.01" value={price} onChange={event=>setFeePrices({...feePrices,prices:{...feePrices.prices,[type]:Number(event.target.value)}})} className="w-full rounded-[8px] border border-atlas-line px-3 py-2.5 pr-14 font-bold outline-none focus:border-atlas-teal focus:ring-4 focus:ring-atlas-teal/10 disabled:bg-slate-50"/><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-500">MAD</span></div></td><td className="px-5 py-3"><div className="relative max-w-36"><input aria-label={`TVA ${feeTypeLabel(type)}`} disabled={readOnly} type="number" min="0" max="100" step="0.01" value={feePrices.tax_rates[type]??0} onChange={event=>setFeePrices({...feePrices,tax_rates:{...feePrices.tax_rates,[type]:Number(event.target.value)}})} className="w-full rounded-[8px] border border-atlas-line px-3 py-2.5 pr-9 font-bold outline-none focus:border-atlas-teal"/><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-500">%</span></div></td><td className="px-5 py-3 text-right"><button type="button" disabled={readOnly||Object.keys(feePrices.prices).length<=1} onClick={()=>removeFeeType(type)} title="Supprimer le type" className="rounded-[8px] p-2.5 text-slate-400 hover:bg-red-50 hover:text-red-600 disabled:cursor-not-allowed disabled:opacity-30"><Trash2 size={17}/></button></td></tr>)}</tbody></table></div>
        <div className="border-t border-atlas-line bg-slate-50/70 p-5"><p className="text-sm font-bold">Ajouter un type</p><div className="mt-3 grid gap-3 sm:grid-cols-[1fr_170px_120px_auto]"><input disabled={readOnly} maxLength={50} value={newFeeType} onChange={event=>setNewFeeType(event.target.value)} placeholder="Ex. Échographie" className="rounded-[8px] border border-atlas-line bg-white px-4 py-3 outline-none focus:border-atlas-teal"/><div className="relative"><input disabled={readOnly} type="number" min="0" step="0.01" value={newFeePrice} onChange={event=>setNewFeePrice(event.target.value)} placeholder="Prix HT" className="w-full rounded-[8px] border border-atlas-line bg-white px-4 py-3 pr-14 outline-none focus:border-atlas-teal"/><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-500">MAD</span></div><div className="relative"><input disabled={readOnly} type="number" min="0" max="100" step="0.01" value={newFeeTaxRate} onChange={event=>setNewFeeTaxRate(event.target.value)} placeholder="TVA" className="w-full rounded-[8px] border border-atlas-line bg-white px-4 py-3 pr-9 outline-none focus:border-atlas-teal"/><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-500">%</span></div><button type="button" disabled={readOnly||!newFeeType.trim()} onClick={addFeeType} className="inline-flex items-center justify-center gap-2 rounded-[8px] bg-atlas-teal px-5 py-3 font-bold text-white hover:bg-atlas-petrol disabled:opacity-40"><Plus size={18}/>Ajouter</button></div><p className="mt-3 text-xs font-semibold text-atlas-petrol">Le prix HT et la TVA seront repris automatiquement lors du choix de ce type d’honoraire.</p></div>
      </section>
      <section id="configuration-paiements" className="scroll-mt-24 rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><CreditCard size={21}/></span><div><h2 className="font-display text-xl font-bold">Modes de règlement</h2><p className="text-xs text-slate-500">Modes propres à votre cabinet, regroupés par type principal</p></div></div><div className="mt-5 grid gap-4 lg:grid-cols-2"><div className="rounded-[10px] border border-emerald-200 bg-emerald-50/40 p-4"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-emerald-100 font-bold text-emerald-700">E</span><div><h3 className="font-bold">Espèces</h3><p className="text-xs text-slate-500">Type principal : ESPECE</p></div></div><div className="mt-3 space-y-2">{paymentMethods.filter(item=>item.main_type==='ESPECE').map(item=><PaymentMethodToggle key={item.id} item={item} readOnly={readOnly} onToggle={()=>void togglePaymentMethod(item)}/>)}</div></div><div className="rounded-[10px] border border-blue-200 bg-blue-50/40 p-4"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-blue-100 font-bold text-blue-700">B</span><div><h3 className="font-bold">Banque</h3><p className="text-xs text-slate-500">Type principal : BANQUE</p></div></div><div className="mt-3 space-y-2">{paymentMethods.filter(item=>item.main_type==='BANQUE').map(item=><PaymentMethodToggle key={item.id} item={item} readOnly={readOnly} onToggle={()=>void togglePaymentMethod(item)}/>)}</div></div></div></section>
      <section className="overflow-hidden rounded-[12px] border border-atlas-line bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-atlas-line p-5 md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><Landmark size={21}/></span><div><h2 className="font-display text-xl font-bold">Comptes bancaires du cabinet</h2><p className="text-xs text-slate-500">Identifiez précisément le compte crédité lors de chaque paiement bancaire.</p></div></div><button type="button" disabled={readOnly} onClick={()=>openBankAccount()} className="inline-flex items-center gap-2 rounded-[8px] bg-atlas-teal px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50"><Plus size={17}/>Ajouter un compte</button></div>
        <div className="divide-y divide-atlas-line">{bankAccounts.length?bankAccounts.map(account=><article key={account.id} className="flex flex-wrap items-center justify-between gap-4 p-5"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h3 className="font-bold text-atlas-petrol">{account.label}</h3>{account.is_default&&<span className="rounded-full bg-emerald-100 px-2.5 py-1 text-[10px] font-bold uppercase text-emerald-700">Par défaut</span>}<span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase ${account.is_active?'bg-blue-50 text-blue-700':'bg-slate-100 text-slate-500'}`}>{account.is_active?'Actif':'Inactif'}</span></div><p className="mt-1 text-sm font-semibold text-slate-600">{account.bank_name} · {account.account_holder}</p><p className="mt-1 font-mono text-xs text-slate-400">RIB •••• {account.rib.replace(/\s/g,'').slice(-4)}</p></div><div className="flex flex-wrap gap-2"><button type="button" disabled={readOnly||account.is_default||!account.is_active} onClick={()=>void updateBankAccount(account,{is_default:true})} className="rounded-[8px] border border-atlas-line px-3 py-2 text-xs font-bold text-atlas-teal disabled:opacity-40">Définir par défaut</button><button type="button" disabled={readOnly} onClick={()=>openBankAccount(account)} title="Modifier" className="rounded-[8px] border border-atlas-line p-2.5 text-slate-500"><Pencil size={16}/></button><button type="button" disabled={readOnly||account.is_default} onClick={()=>void updateBankAccount(account,{is_active:!account.is_active})} className="rounded-[8px] border border-atlas-line px-3 py-2 text-xs font-bold text-slate-600 disabled:opacity-40">{account.is_active?'Désactiver':'Activer'}</button></div></article>):<div className="p-8 text-center"><Landmark size={30} className="mx-auto text-slate-300"/><p className="mt-3 font-bold text-slate-600">Aucun compte bancaire configuré</p><p className="mt-1 text-xs text-slate-400">Les paiements par carte, virement ou chèque nécessiteront un compte.</p></div>}</div>
        {showBankAccount&&<div className="border-t border-atlas-line bg-slate-50/70 p-5 md:p-6"><div className="flex items-center justify-between"><div><h3 className="font-bold">{editingBankAccountId?'Modifier le compte':'Nouveau compte bancaire'}</h3><p className="mt-1 text-xs text-slate-500">Ces informations restent internes au cabinet.</p></div><button type="button" onClick={()=>setShowBankAccount(false)} className="rounded-full p-2 text-slate-500 hover:bg-white"><X size={18}/></button></div><div className="mt-4 grid gap-4 md:grid-cols-2"><label className="text-sm font-bold">Libellé *<input required={showBankAccount} value={bankAccountForm.label} onChange={event=>setBankAccountForm({...bankAccountForm,label:event.target.value})} placeholder="Ex. Compte principal" className={fieldClass}/></label><label className="text-sm font-bold">Banque *<input required={showBankAccount} value={bankAccountForm.bank_name} onChange={event=>setBankAccountForm({...bankAccountForm,bank_name:event.target.value})} placeholder="Ex. Attijariwafa bank" className={fieldClass}/></label><label className="text-sm font-bold">Titulaire *<input required={showBankAccount} value={bankAccountForm.account_holder} onChange={event=>setBankAccountForm({...bankAccountForm,account_holder:event.target.value})} className={fieldClass}/></label><label className="text-sm font-bold">RIB *<input required={showBankAccount} minLength={16} maxLength={32} value={bankAccountForm.rib} onChange={event=>setBankAccountForm({...bankAccountForm,rib:event.target.value.replace(/[^A-Za-z0-9 ]/g,'')})} placeholder="24 chiffres" className={fieldClass}/></label><label className="text-sm font-bold md:col-span-2">IBAN (facultatif)<input maxLength={34} value={bankAccountForm.iban} onChange={event=>setBankAccountForm({...bankAccountForm,iban:event.target.value.replace(/[^A-Za-z0-9 ]/g,'')})} className={fieldClass}/></label></div><label className="mt-4 flex items-center gap-3 rounded-[8px] border border-atlas-line bg-white p-3 text-sm font-bold"><input type="checkbox" checked={bankAccountForm.is_default} onChange={event=>setBankAccountForm({...bankAccountForm,is_default:event.target.checked,is_active:event.target.checked?true:bankAccountForm.is_active})} className="h-4 w-4 accent-atlas-teal"/>Utiliser ce compte par défaut pour les paiements bancaires</label><div className="mt-4 flex justify-end gap-2"><button type="button" onClick={()=>setShowBankAccount(false)} className="rounded-[8px] border border-atlas-line px-4 py-2.5 text-sm font-bold text-slate-600">Annuler</button><button type="button" disabled={readOnly||!bankAccountForm.label.trim()||!bankAccountForm.bank_name.trim()||!bankAccountForm.account_holder.trim()||bankAccountForm.rib.replace(/\s/g,'').length<16} onClick={()=>void saveBankAccount()} className="rounded-[8px] bg-atlas-teal px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40">Enregistrer le compte</button></div></div>}
      </section>
      <SupplierCatalogSettings readOnly={readOnly}/>
      <section id="relances-automatiques" className="scroll-mt-24 rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><BellRing size={21}/></span><div><h2 className="font-display text-xl font-bold">Relances automatiques</h2><p className="text-xs text-slate-500">Réglez les rappels généraux. Chaque rendez-vous peut ensuite avoir sa propre règle.</p></div></div>
        <div className="mt-5 grid gap-4">
          <article className="rounded-[10px] border border-atlas-teal/30 bg-atlas-mist/20 p-4"><div className="flex items-start justify-between gap-4"><div><h3 className="font-bold">Rendez-vous</h3><p className="mt-1 text-xs text-slate-500">Par défaut, rappel la veille (J‑1).</p></div><input type="checkbox" disabled={readOnly} checked={reminderSettings.appointments.enabled} onChange={event=>setReminderSettings({...reminderSettings,appointments:{...reminderSettings.appointments,enabled:event.target.checked}})} className="h-5 w-5 accent-atlas-teal"/></div>{reminderSettings.appointments.enabled&&<div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="text-sm font-bold">Délai avant le rendez-vous<select disabled={readOnly} value={reminderSettings.appointments.offset_minutes} onChange={event=>setReminderSettings({...reminderSettings,appointments:{...reminderSettings.appointments,offset_minutes:Number(event.target.value)}})} className={fieldClass}><option value={180}>3 heures avant</option><option value={360}>6 heures avant</option><option value={720}>12 heures avant</option><option value={1440}>La veille (J‑1)</option><option value={2880}>2 jours avant</option><option value={4320}>3 jours avant</option><option value={10080}>7 jours avant</option></select></label><ReminderChannelChoices channels={reminderSettings.appointments.channels} disabled={readOnly} onToggle={channel=>toggleReminderChannel('appointments',channel)}/></div>}</article>
          <div className="grid gap-4 lg:grid-cols-2">
            <article className="rounded-[10px] border border-violet-200 bg-violet-50/40 p-4"><div className="flex items-start justify-between gap-4"><div><h3 className="font-bold">Chèques à encaisser</h3><p className="mt-1 text-xs text-slate-500">Alerte interne avant la date prévue d’encaissement.</p></div><input type="checkbox" disabled={readOnly} checked={reminderSettings.cheques.enabled} onChange={event=>setReminderSettings({...reminderSettings,cheques:{...reminderSettings.cheques,enabled:event.target.checked}})} className="h-5 w-5 accent-atlas-teal"/></div>{reminderSettings.cheques.enabled&&<div className="mt-4 grid grid-cols-2 gap-3"><label className="text-xs font-bold">Prévenir<input type="number" min="0" max="30" disabled={readOnly} value={reminderSettings.cheques.days_before} onChange={event=>setReminderSettings({...reminderSettings,cheques:{...reminderSettings.cheques,days_before:Number(event.target.value)}})} className={fieldClass}/><span className="mt-1 block text-slate-400">jour(s) avant</span></label><label className="text-xs font-bold">Répéter tous les<input type="number" min="1" max="30" disabled={readOnly} value={reminderSettings.cheques.repeat_days} onChange={event=>setReminderSettings({...reminderSettings,cheques:{...reminderSettings.cheques,repeat_days:Number(event.target.value)}})} className={fieldClass}/><span className="mt-1 block text-slate-400">jour(s) tant que non encaissé</span></label></div>}</article>
          <article className="rounded-[10px] border border-amber-200 bg-amber-50/40 p-4"><div className="flex items-start justify-between gap-4"><div><h3 className="font-bold">Impayés</h3><p className="mt-1 text-xs text-slate-500">Relancer les patients ayant un reste à payer.</p></div><input type="checkbox" disabled={readOnly} checked={reminderSettings.payments.enabled} onChange={event=>setReminderSettings({...reminderSettings,payments:{...reminderSettings.payments,enabled:event.target.checked}})} className="h-5 w-5 accent-atlas-teal"/></div>{reminderSettings.payments.enabled&&<><div className="mt-4 grid grid-cols-2 gap-3"><label className="text-xs font-bold">Après<input type="number" min="0" max="365" disabled={readOnly} value={reminderSettings.payments.overdue_days} onChange={event=>setReminderSettings({...reminderSettings,payments:{...reminderSettings.payments,overdue_days:Number(event.target.value)}})} className={fieldClass}/><span className="mt-1 block text-slate-400">jour(s) d’impayé</span></label><label className="text-xs font-bold">Répéter tous les<input type="number" min="1" max="90" disabled={readOnly} value={reminderSettings.payments.repeat_days} onChange={event=>setReminderSettings({...reminderSettings,payments:{...reminderSettings.payments,repeat_days:Number(event.target.value)}})} className={fieldClass}/><span className="mt-1 block text-slate-400">jour(s)</span></label></div><ReminderChannelChoices channels={reminderSettings.payments.channels} disabled={readOnly} onToggle={channel=>toggleReminderChannel('payments',channel)}/></>}</article>
            <article className="rounded-[10px] border border-blue-200 bg-blue-50/40 p-4"><div className="flex items-start justify-between gap-4"><div><h3 className="font-bold">Dossiers CNSS/CNOPS en attente</h3><p className="mt-1 text-xs text-slate-500">Informer le patient lorsqu’un dossier reste bloqué.</p></div><input type="checkbox" disabled={readOnly} checked={reminderSettings.cnss.enabled} onChange={event=>setReminderSettings({...reminderSettings,cnss:{...reminderSettings.cnss,enabled:event.target.checked}})} className="h-5 w-5 accent-atlas-teal"/></div>{reminderSettings.cnss.enabled&&<><div className="mt-4 grid grid-cols-2 gap-3"><label className="text-xs font-bold">Après<input type="number" min="1" max="365" disabled={readOnly} value={reminderSettings.cnss.pending_days} onChange={event=>setReminderSettings({...reminderSettings,cnss:{...reminderSettings.cnss,pending_days:Number(event.target.value)}})} className={fieldClass}/><span className="mt-1 block text-slate-400">jour(s) en attente</span></label><label className="text-xs font-bold">Répéter tous les<input type="number" min="1" max="90" disabled={readOnly} value={reminderSettings.cnss.repeat_days} onChange={event=>setReminderSettings({...reminderSettings,cnss:{...reminderSettings.cnss,repeat_days:Number(event.target.value)}})} className={fieldClass}/><span className="mt-1 block text-slate-400">jour(s)</span></label></div><ReminderChannelChoices channels={reminderSettings.cnss.channels} disabled={readOnly} onToggle={channel=>toggleReminderChannel('cnss',channel)}/></>}</article>
          </div>
        </div>
      </section>
      <section className="rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><Building2 size={21}/></span><div><h2 className="font-display text-xl font-bold">Identité du cabinet</h2><p className="text-xs text-slate-500">Informations visibles par les patients</p></div></div><div className="flex items-center gap-2 rounded-[8px] bg-slate-50 px-3 py-2"><div><p className="text-[10px] font-bold uppercase text-slate-400">Code cabinet</p><p className="font-mono text-sm font-bold text-atlas-petrol">{cabinet.slug}</p></div><button type="button" onClick={()=>void copyCode()} title="Copier le code" className="rounded-md p-2 text-atlas-teal hover:bg-atlas-mist">{copied?<Check size={17}/>:<Clipboard size={17}/>}</button></div></div>
        <div className="mt-6 grid gap-4 md:grid-cols-2"><label><span className="text-sm font-bold">Nom du cabinet *</span><input required minLength={2} disabled={readOnly} value={cabinet.name??''} onChange={event=>set('name',event.target.value)} className={fieldClass}/></label><label><span className="text-sm font-bold">Spécialité du médecin *</span><select required disabled={readOnly} value={cabinet.specialty??''} onChange={event=>set('specialty',event.target.value)} className={fieldClass}><option value="" disabled>Sélectionnez une spécialité</option>{cabinet.specialty&&!specialties.includes(cabinet.specialty)&&<option value={cabinet.specialty}>{cabinet.specialty}</option>}{specialties.map(specialty=><option key={specialty} value={specialty}>{specialty}</option>)}</select></label><label className="md:col-span-2"><span className="text-sm font-bold">Téléphone *</span><input required type="tel" pattern={phonePatternHtml} title="Exemple valide : 05 22 00 00 00 ou +212 5 22 00 00 00" aria-invalid={!isValidPhone(cabinet.phone??'',true)} disabled={readOnly} value={cabinet.phone??''} onChange={event=>set('phone',phoneInput(event.target.value))} placeholder={phonePlaceholder} className={`${fieldClass} ${isValidPhone(cabinet.phone??'',true)?'':'border-red-400 focus:border-red-500 focus:ring-red-100'}`}/>{!isValidPhone(cabinet.phone??'',true)&&<span className="mt-1.5 block text-xs font-bold text-red-600">Numéro invalide. Utilisez par exemple 05 22 00 00 00 ou +212 5 22 00 00 00.</span>}</label></div>
      </section>

      <section className="overflow-hidden rounded-[12px] border border-atlas-line bg-white shadow-sm"><div className="p-5 md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><MapPin size={22}/></span><div><h2 className="font-display text-xl font-bold">Localisation du médecin</h2><p className="text-xs text-slate-500">Indiquez précisément où les patients peuvent vous trouver</p></div></div><div className="mt-6 grid gap-4 md:grid-cols-[1fr_0.7fr]"><label><span className="text-sm font-bold">Adresse professionnelle *</span><input required minLength={5} disabled={readOnly} value={cabinet.address??''} onChange={event=>set('address',event.target.value)} placeholder="N°, rue, quartier, étage…" className={fieldClass}/></label><label><span className="text-sm font-bold">Ville *</span><input required minLength={2} disabled={readOnly} value={cabinet.city??''} onChange={event=>set('city',event.target.value)} placeholder="Ex. Casablanca" className={fieldClass}/></label></div><div className="mt-5 flex flex-wrap items-center justify-between gap-3 rounded-[10px] bg-atlas-mist p-4"><div className="flex min-w-0 items-center gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-white text-atlas-teal shadow-sm"><MapPin size={19}/></span><div className="min-w-0"><p className="text-xs font-bold uppercase tracking-wide text-atlas-teal">Adresse affichée aux patients</p><p className="mt-1 truncate text-sm font-bold text-atlas-petrol">{[cabinet.address,cabinet.city].filter(Boolean).join(', ')||'Localisation à renseigner'}</p></div></div>{(cabinet.address||cabinet.city)&&<a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${cabinet.address}, ${cabinet.city}`)}`} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-[8px] bg-atlas-teal px-4 py-2.5 text-sm font-bold text-white hover:bg-atlas-petrol"><Navigation size={16}/>Voir l’itinéraire</a>}</div></div>{(cabinet.address||cabinet.city)?<iframe title="Localisation du cabinet médical" src={`https://www.google.com/maps?q=${encodeURIComponent(`${cabinet.address}, ${cabinet.city}`)}&output=embed`} loading="lazy" referrerPolicy="no-referrer-when-downgrade" className="h-72 w-full border-0"/>:<div className="grid h-56 place-items-center border-t border-atlas-line bg-slate-50 text-center"><div><MapPin size={34} className="mx-auto text-slate-300"/><p className="mt-3 text-sm font-semibold text-slate-500">Renseignez l’adresse pour afficher la carte.</p></div></div>}</section>

      <section className="rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><Palette size={21}/></span><div><h2 className="font-display text-xl font-bold">Couleur de l’interface</h2><p className="text-xs text-slate-500">Personnalisez l’interface professionnelle du cabinet : boutons, onglets, icônes, agenda et accents visuels.</p></div></div><div className="mt-6 flex flex-wrap items-center gap-4"><label className="flex items-center gap-3 rounded-[10px] border border-atlas-line bg-slate-50 p-3"><input type="color" disabled={readOnly} value={cabinet.primary_color||DEFAULT_COLOR} onChange={event=>set('primary_color',event.target.value)} className="h-12 w-16 cursor-pointer rounded border-0 bg-transparent disabled:cursor-default"/><span><b className="block text-sm">Couleur principale</b><span className="text-xs font-semibold uppercase text-slate-400">{cabinet.primary_color||DEFAULT_COLOR}</span></span></label><div className="flex flex-wrap gap-2">{['#0f8a7a','#2563eb','#7c3aed','#db2777','#ea580c','#15803d'].map(color=><button key={color} type="button" disabled={readOnly} onClick={()=>set('primary_color',color)} aria-label={`Choisir ${color}`} className={`h-10 w-10 rounded-full border-4 shadow-sm transition hover:scale-110 disabled:opacity-50 ${(cabinet.primary_color||DEFAULT_COLOR).toLowerCase()===color?'border-slate-800':'border-white'}`} style={{backgroundColor:color}}/>)}</div><button type="button" disabled={readOnly} onClick={()=>set('primary_color',DEFAULT_COLOR)} className="rounded-[8px] border border-atlas-line px-4 py-2.5 text-sm font-bold text-slate-600 hover:border-atlas-teal hover:text-atlas-teal">Couleur par défaut</button></div><p className="mt-4 rounded-[8px] bg-atlas-mist px-4 py-3 text-xs font-semibold text-atlas-petrol">L’aperçu est immédiat. Cliquez sur « Enregistrer la configuration » pour conserver cette couleur pour le médecin et son personnel. L’espace patient conserve toujours les couleurs FADAA.</p></section>

      <section className="rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><ImagePlus size={21}/></span><div><h2 className="font-display text-xl font-bold">Logo du médecin / cabinet</h2><p className="text-xs text-slate-500">Ce logo est ajouté automatiquement à l’en-tête de chaque nouvelle ordonnance et aux documents du cabinet.</p></div></div>
        <div className="mt-6"><label><span className="text-sm font-bold">Fichier du logo professionnel</span><div className="mt-2 flex flex-wrap items-center gap-4 rounded-[10px] border border-dashed border-atlas-line bg-slate-50 p-4">{logoPreview?<img src={logoPreview} alt="Logo professionnel du médecin" className="h-24 w-36 rounded-[8px] bg-white object-contain p-2 shadow-sm"/>:<div className="grid h-24 w-36 place-items-center rounded-[8px] bg-atlas-mist text-atlas-teal"><ImagePlus size={26}/></div>}<div className="min-w-0 flex-1"><input disabled={readOnly||uploadingLogo} type="file" accept="image/png,image/jpeg,image/webp" onChange={event=>void chooseLogo(event.target.files?.[0]??null)} className="w-full text-sm file:mr-3 file:rounded-[8px] file:border-0 file:bg-atlas-teal file:px-4 file:py-2 file:font-bold file:text-white disabled:cursor-wait disabled:opacity-60"/><p className={`mt-2 text-xs font-semibold ${logoError?'text-red-600':uploadingLogo?'text-amber-600':cabinet.logo_url?'text-emerald-700':'text-slate-400'}`}>{logoError||(uploadingLogo?'Enregistrement du logo…':cabinet.logo_url?'Logo enregistré · utilisé sur les nouvelles ordonnances, factures et reçus':'PNG, JPG ou WEBP · le logo est enregistré dès sa sélection')}</p></div></div></label></div>
      </section>

      {schedule&&<section className="rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><Clock3 size={21}/></span><div><h2 className="font-display text-xl font-bold">Horaires et disponibilités</h2><p className="text-xs text-slate-500">Cochez les jours ouverts et indiquez les heures utiles.</p></div></div><button type="button" onClick={()=>setShowLeave(true)} className="inline-flex items-center gap-2 rounded-[8px] border border-atlas-line px-4 py-2.5 text-sm font-bold text-atlas-petrol hover:border-atlas-teal"><CalendarOff size={17}/>Ajouter une absence</button></div>
        <div className="mt-5 space-y-2">{schedule.days.map((day,index)=><div key={day.weekday} className={`grid items-center gap-3 rounded-[9px] border p-3 ${day.is_working?'border-atlas-teal/30 bg-atlas-mist/20':'border-atlas-line bg-slate-50'} md:grid-cols-[110px_repeat(4,1fr)]`}><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" disabled={readOnly} checked={day.is_working} onChange={event=>setSchedule({...schedule,days:schedule.days.map((item,i)=>i===index?{...item,is_working:event.target.checked}:item)})} className="h-4 w-4 accent-atlas-teal"/>{['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'][day.weekday]}</label>{day.is_working&&([['start_time','Ouverture'],['end_time','Fermeture'],['break_start_time','Début pause'],['break_end_time','Fin pause']] as const).map(([key,label])=><label key={key} className="text-[11px] font-bold text-slate-500">{label}<input type="time" disabled={readOnly} value={day[key]??''} onChange={event=>setSchedule({...schedule,days:schedule.days.map((item,i)=>i===index?{...item,[key]:event.target.value}:item)})} className="mt-1 w-full rounded-[7px] border border-atlas-line bg-white px-2 py-2 text-sm text-atlas-ink"/></label>)}</div>)}</div>
        <label className="mt-4 block max-w-xs text-sm font-bold">Durée d’une consultation<select disabled={readOnly} value={schedule.config.default_duration_minutes} onChange={event=>setSchedule({...schedule,config:{...schedule.config,default_duration_minutes:Number(event.target.value)}})} className={fieldClass}>{[10,15,20,30,45,60].map(value=><option key={value} value={value}>{value} minutes</option>)}</select></label>
        {timeOffs.length>0&&<p className="mt-4 text-xs font-semibold text-slate-500">{timeOffs.length} absence{timeOffs.length>1?'s':''} configurée{timeOffs.length>1?'s':''}.</p>}
      </section>}

      <section className="rounded-[12px] border border-atlas-line bg-white p-5 shadow-sm md:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-atlas-mist text-atlas-teal"><UsersRound size={21}/></span><div><h2 className="font-display text-xl font-bold">Espace patient</h2><p className="text-xs text-slate-500">Activez uniquement les fonctions que vous souhaitez proposer</p></div></div>
        <div className="mt-6 grid gap-3 md:grid-cols-2">{([['patient_can_request_appointment','Demander un rendez-vous','Le patient peut envoyer une nouvelle demande'],['patient_can_confirm_appointment','Confirmer un rendez-vous','Le patient peut confirmer lui-même'],['patient_can_cancel_appointment','Annuler un rendez-vous','Le patient peut annuler depuis son espace'],['patient_can_view_payments','Voir les paiements et RAP','Les informations financières sont visibles'],['patient_can_download_documents','Télécharger les documents','Les documents partagés sont téléchargeables'],['patient_requires_validation','Valider les nouveaux comptes','Votre accord est requis avant la connexion'],['patient_cin_required','CIN obligatoire','Exiger le numéro de CIN dans le dossier patient'],['patient_cin_document_required','Document CIN obligatoire','Exiger une copie uniquement si la politique du cabinet le prévoit']] as const).map(([key,label,description])=><label key={key} className="flex cursor-pointer items-center justify-between gap-4 rounded-[10px] border border-atlas-line p-4 transition hover:border-atlas-teal/40"><span><span className="block text-sm font-bold">{label}</span><span className="mt-1 block text-xs leading-5 text-slate-500">{description}</span></span><input type="checkbox" disabled={readOnly} checked={patientSettings[key]} onChange={event=>setPatientSettings({...patientSettings,[key]:event.target.checked})} className="h-5 w-5 shrink-0 accent-atlas-teal"/></label>)}</div>
      </section>

      <div className="sticky bottom-4 flex flex-wrap items-center justify-between gap-3 rounded-[12px] border border-atlas-line bg-white/95 p-4 shadow-lg backdrop-blur"><div className="flex items-center gap-2 text-sm text-slate-500"><Settings2 size={18}/><span>Les modifications s’appliquent immédiatement après enregistrement.</span></div><button disabled={readOnly||saving||uploadingLogo} className="inline-flex w-full items-center justify-center gap-2 rounded-[8px] bg-atlas-teal px-6 py-3 font-bold text-white hover:bg-atlas-petrol disabled:opacity-50 sm:w-auto"><Save size={18}/>{saving?'Enregistrement…':'Enregistrer la configuration'}</button></div>
      {showLeave&&<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/55 p-4"><section className="w-full max-w-lg rounded-[14px] bg-white p-5 shadow-2xl"><div className="flex items-center justify-between"><div><h3 className="font-display text-xl font-bold">Congé ou absence</h3><p className="mt-1 text-xs text-slate-500">Indiquez la période et le motif.</p></div><button type="button" onClick={()=>setShowLeave(false)} className="rounded-full p-2 text-slate-400 hover:bg-slate-100"><X size={19}/></button></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-sm font-bold">Du<input type="date" value={leave.start_date} onChange={event=>setLeave({...leave,start_date:event.target.value})} className={fieldClass}/></label><label className="text-sm font-bold">Au<input type="date" min={leave.start_date} value={leave.end_date} onChange={event=>setLeave({...leave,end_date:event.target.value})} className={fieldClass}/></label><label className="text-sm font-bold sm:col-span-2">Motif<input value={leave.reason} onChange={event=>setLeave({...leave,reason:event.target.value})} placeholder="Ex. Congé annuel" className={fieldClass}/></label></div><button type="button" onClick={()=>void addLeave()} className="mt-5 w-full rounded-[8px] bg-atlas-teal px-5 py-3 font-bold text-white">Enregistrer l’absence</button></section></div>}
    </form>}
  </div></MedecinLayout>
}
